module expected_area (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] k,\n    input real x [0:7],\n    input real y [0:7],\n    output real result,\n    output done\n);\n    \n    // Parameters\n    parameter MAX_N = 8;\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_S = 3'd1;\n    localparam [2:0] COMPUTE_P = 3'd2;\n    localparam [2:0] NEXT_D = 3'd3;\n    localparam [2:0] DONE = 3'd4;\n    \n    // Combination ROM: comb[a][b] = C(a,b)\n    real comb [0:MAX_N][0:MAX_N];\n    \n    integer i, j, a;\n    initial begin\n        // Initialize combination table\n        for (i = 0; i <= MAX_N; i = i + 1) begin\n            for (j = 0; j <= MAX_N; j = j + 1) begin\n                if (j > i) begin\n                    comb[i][j] = 0.0;\n                end else if (j == 0) begin\n                    comb[i][j] = 1.0;\n                end else begin\n                    real val = 1.0;\n                    for (a = 0; a < j; a = a + 1) begin\n                        val = val * (i - a) / (a + 1);\n                    end\n                    comb[i][j] = val;\n                end\n            end\n        end\n    end\n    \n    // Registers\n    reg [2:0] state;\n    reg [3:0] d;\n    reg [3:0] i_idx;\n    reg [3:0] max_d_reg;\n    reg [3:0] a_reg;\n    real total_area;\n    real S_d;\n    real p_d;\n    real C_n_k;\n    real result_reg;\n    reg done_reg;\n    \n    // Wires\n    wire [3:0] j_idx;\n    assign j_idx = (i_idx + d < n) ? (i_idx + d) : (i_idx + d - n);\n    \n    wire real term;\n    assign term = x[i_idx] * y[j_idx] - x[j_idx] * y[i_idx];\n    \n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done_reg <= 1'b0;\n            total_area <= 0.0;\n            S_d <= 0.0;\n            p_d <= 0.0;\n            result_reg <= 0.0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done_reg <= 1'b0;\n                    if (start) begin\n                        // Initialize computation\n                        total_area <= 0.0;\n                        // Compute max_d = n - k + 1 (ensure non-negative)\n                        max_d_reg <= (n > k-1) ? (n - k + 1) : 0;\n                        // Store C(n,k)\n                        C_n_k <= comb[n][k];\n                        // Set d to 1\n                        d <= 4'd1;\n                        // Reset i and S_d\n                        i_idx <= 4'd0;\n                        S_d <= 0.0;\n                        state <= COMPUTE_S;\n                    end\n                end\n                \n                COMPUTE_S: begin\n                    // Accumulate term into S_d\n                    S_d <= S_d + term;\n                    // Increment i\n                    i_idx <= i_idx + 4'd1;\n                    // Check if we have processed all vertices\n                    if (i_idx + 4'd1 < n) begin\n                        // Continue looping\n                        state <= COMPUTE_S;\n                    end else begin\n                        // Finished all i for this d\n                        state <= COMPUTE_P;\n                    end\n                end\n                \n                COMPUTE_P: begin\n                    // Compute p_d\n                    if (d > max_d_reg) begin\n                        p_d <= 0.0;\n                    end else begin\n                        a_reg <= n - d - 4'd1;\n                        // p_d = C(a_reg, k-2) / C_n_k\n                        p_d <= comb[a_reg][k-2] / C_n_k;\n                    end\n                    // Update total_area\n                    total_area <= total_area + S_d * p_d;\n                    // Move to next d\n                    state <= NEXT_D;\n                end\n                \n                NEXT_D: begin\n                    d <= d + 4'd1;\n                    // Reset i and S_d for next distance\n                    i_idx <= 4'd0;\n                    S_d <= 0.0;\n                    // Check if we have processed all distances\n                    if (d < n - 4'd1) begin\n                        state <= COMPUTE_S;\n                    end else begin\n                        // Compute final result\n                        result_reg <= -0.5 * total_area;\n                        state <= DONE;\n                        done_reg <= 1'b1;\n                    end\n                end\n                \n                DONE: begin\n                    // Wait for next start\n                    if (start) begin\n                        // Re-initialize as in IDLE\n                        done_reg <= 1'b0;\n                        total_area <= 0.0;\n                        max_d_reg <= (n > k-1) ? (n - k + 1) : 0;\n                        C_n_k <= comb[n][k];\n                        d <= 4'd1;\n                        i_idx <= 4'd0;\n                        S_d <= 0.0;\n                        state <= COMPUTE_S;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \n    // Output assignments\n    assign result = result_reg;\n    assign done = done_reg;\n    \nendmodule